const observers = new Map();

export function initScrollWatcher(scrollContainer, sentinel, dotNetRef) {
    disposeScrollWatcher(scrollContainer);

    const observer = new IntersectionObserver((entries) => {
        if (entries[0].isIntersecting) {
            dotNetRef.invokeMethodAsync('LoadMoreMessages');
        }
    }, { root: scrollContainer, threshold: 0.1 });

    observer.observe(sentinel);
    observers.set(scrollContainer, observer);
}

export function disposeScrollWatcher(scrollContainer) {
    const observer = observers.get(scrollContainer);
    if (observer) {
        observer.disconnect();
        observers.delete(scrollContainer);
    }
}

export function scrollToBottom(element) {
    if (element) {
        element.scrollTop = element.scrollHeight;
    }
}

