.message-item {
    padding: 8px 16px;
    position: relative;
    transition: background-color 0.1s;
}

.message-item:hover {
    background-color: #f8f8f8;
}

.message-meta {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.author {
    font-weight: 700;
    font-size: 0.95rem;
    color: #1a1a1a;
}

.timestamp {
    font-size: 0.75rem;
    color: #999;
}

.message-content {
    font-size: 0.93rem;
    color: #333;
    line-height: 1.5;
    white-space: pre-wrap;
    word-break: break-word;
}

.reactions-row {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 4px;
}

.thread-link {
    background: none;
    border: none;
    color: #4a90d9;
    font-size: 0.82rem;
    cursor: pointer;
    padding: 2px 0;
    margin-top: 4px;
    display: block;
    font-weight: 600;
}

.thread-link:hover {
    text-decoration: underline;
}

.hover-actions {
    position: absolute;
    top: 4px;
    right: 12px;
    display: flex;
    gap: 4px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 6px;
    padding: 2px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.action-btn {
    border: none;
    background: transparent;
    cursor: pointer;
    font-size: 0.8rem;
    padding: 4px 8px;
    border-radius: 4px;
    color: #555;
    transition: background-color 0.15s;
}

.action-btn:hover {
    background: #f0f0f0;
}

@implements IAsyncDisposable
@inject IJSRuntime JS

<div class="message-list" @ref="_scrollContainer">
    @if (HasMoreMessages)
    {
        <div @ref="_sentinel" style="height:1px"></div>
    }
    @if (IsLoadingMore)
    {
        <div class="loading-indicator">Loading older messages…</div>
    }
    @foreach (var message in Messages)
    {
        <MessageItem Message="message"
                     ReplyCount="GetReplyCount(message.Id)"
                     OnOpenThread="OnOpenThread"
                     OnReact="OnReact" />
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public bool HasMoreMessages { get; set; }
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private ElementReference _scrollContainer;
    private ElementReference _sentinel;
    private IJSObjectReference? _module;
    private DotNetObjectReference<MessageList>? _dotNetRef;
    private bool _jsInitialized;

    private int GetReplyCount(int messageId) =>
        ThreadReplyCounts.GetValueOrDefault(messageId);

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _module = await JS.InvokeAsync<IJSObjectReference>("import", "./js/chat-scroll.js");
            _jsInitialized = true;
            await ScrollToBottom();
        }

        if (_jsInitialized && HasMoreMessages)
        {
            await _module!.InvokeVoidAsync("initScrollWatcher", _scrollContainer, _sentinel, _dotNetRef);
        }
    }

    public async Task ScrollToBottom()
    {
        if (_module is not null)
        {
            await _module.InvokeVoidAsync("scrollToBottom", _scrollContainer);
        }
    }

    [JSInvokable]
    public async Task LoadMoreMessages()
    {
        await OnLoadMore.InvokeAsync();
    }

    public async ValueTask DisposeAsync()
    {
        if (_module is not null)
        {
            try
            {
                await _module.InvokeVoidAsync("disposeScrollWatcher", _scrollContainer);
            }
            catch (JSDisconnectedException) { }
            await _module.DisposeAsync();
        }
        _dotNetRef?.Dispose();
    }
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.loading-indicator {
    text-align: center;
    padding: 8px;
    color: #999;
    font-size: 0.85rem;
}

.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #fafafa;
}

.thread-header {
