+@page "/chat"
+@layout ChatLayout
+@rendermode InteractiveServer
+@using sv_8c3097872c634818b9e8f891f6cbf6bb.Services
+@inject IChatService ChatService
+
+<PageTitle>Chat</PageTitle>
+
+<div class="chat-container">
+    <div class="sidebar-column">
+        <ChannelSidebar Channels="channels"
+                        ActiveChannelId="activeChannelId"
+                        OnChannelSelected="SelectChannel" />
+    </div>
+
+    <div class="main-column">
+        @if (activeChannel is not null)
+        {
+            <div class="main-header">
+                <h3># @activeChannel.Name</h3>
+                <span class="header-description">@activeChannel.Description</span>
+            </div>
+
+            <MessageList Messages="messages"
+                         ThreadReplyCounts="threadReplyCounts"
+                         HasMoreMessages="hasMoreMessages"
+                         IsLoadingMore="isLoadingMore"
+                         OnLoadMore="LoadOlderMessages"
+                         OnOpenThread="OpenThread"
+                         OnReact="HandleReaction"
+                         @ref="messageListRef" />
+
+            <MessageInput Placeholder="@($"Message #{activeChannel.Name}")"
+                          OnSend="SendMessage" />
+        }
+        else
+        {
+            <div class="no-channel-selected">
+                <p>Select a channel to start chatting</p>
+            </div>
+        }
+    </div>
+
+    @if (isThreadOpen && threadRootMessage is not null)
+    {
+        <div class="thread-column">
+            <ThreadPanel RootMessage="threadRootMessage"
+                         Replies="threadMessages"
+                         OnClose="CloseThread"
+                         OnSendReply="SendThreadReply"
+                         OnReact="HandleReaction" />
+        </div>
+    }
+</div>
+
+@code {
+    private List<Channel> channels = [];
+    private Channel? activeChannel;
+    private int activeChannelId;
+    private List<Message> messages = [];
+    private Dictionary<int, int> threadReplyCounts = [];
+    private bool hasMoreMessages = true;
+    private bool isLoadingMore;
+    private const int PageSize = 30;
+
+    private bool isThreadOpen;
+    private Message? threadRootMessage;
+    private List<Message> threadMessages = [];
+    private MessageList? messageListRef;
+
+    protected override async Task OnInitializedAsync()
+    {
+        channels = await ChatService.GetChannelsAsync();
+        if (channels.Count > 0)
+        {
+            await SelectChannel(channels[0]);
+        }
+    }
+
+    private async Task SelectChannel(Channel channel)
+    {
+        activeChannel = channel;
+        activeChannelId = channel.Id;
+        messages = [];
+        threadReplyCounts = [];
+        hasMoreMessages = true;
+        CloseThread();
+
+        var loaded = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
+        messages = loaded;
+        hasMoreMessages = loaded.Count >= PageSize;
+
+        await ChatService.MarkChannelReadAsync(channel.Id);
+
+        var idx = channels.FindIndex(c => c.Id == channel.Id);
+        if (idx >= 0)
+        {
+            channels[idx] = channel with { UnreadCount = 0 };
+        }
+    }
+
+    private async Task LoadOlderMessages()
+    {
+        if (isLoadingMore || !hasMoreMessages) return;
+
+        isLoadingMore = true;
+        StateHasChanged();
+
+        var older = await ChatService.GetMessagesAsync(activeChannelId, messages.Count, PageSize);
+        if (older.Count > 0)
+        {
+            messages.InsertRange(0, older);
+        }
+        hasMoreMessages = older.Count >= PageSize;
+        isLoadingMore = false;
+    }
+
+    private async Task SendMessage(string content)
+    {
+        var sent = await ChatService.SendMessageAsync(activeChannelId, content, null);
+        messages.Add(sent);
+
+        if (messageListRef is not null)
+        {
+            await messageListRef.ScrollToBottom();
+        }
+    }
+
+    private async Task OpenThread(int rootMessageId)
+    {
+        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootMessageId);
+        if (threadRootMessage is null) return;
+
+        threadMessages = await ChatService.GetThreadAsync(rootMessageId);
+        threadReplyCounts[rootMessageId] = threadMessages.Count;
+        isThreadOpen = true;
+    }
+
+    private void CloseThread()
+    {
+        isThreadOpen = false;
+        threadRootMessage = null;
+        threadMessages = [];
+    }
+
+    private async Task SendThreadReply(string content)
+    {
+        if (threadRootMessage is null) return;
+
+        var reply = await ChatService.SendMessageAsync(activeChannelId, content, threadRootMessage.Id);
+        threadMessages.Add(reply);
+        threadReplyCounts[threadRootMessage.Id] = threadMessages.Count;
+    }
+
+    private async Task HandleReaction((int MessageId, string Emoji) reaction)
+    {
+        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);
+
+        // Refresh messages to reflect the new reaction
+        if (activeChannel is not null)
+        {
+            var refreshed = await ChatService.GetMessagesAsync(activeChannelId, 0, messages.Count);
+            if (refreshed.Count > 0)
+            {
+                messages = refreshed;
+            }
+        }
+
+        if (isThreadOpen && threadRootMessage is not null)
+        {
+            threadMessages = await ChatService.GetThreadAsync(threadRootMessage.Id);
+        }
+    }
+}
