.chat-container {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

.sidebar-column {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
    border-right: 1px solid #3a3d42;
}

.main-column {
    flex: 1;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    background: #fff;
    min-width: 0;
}

.thread-column {
    width: 25%;
    min-width: 280px;
    max-width: 400px;
    flex-shrink: 0;
    border-left: 1px solid #e0e0e0;
}

.main-header {
    padding: 12px 16px;
    border-bottom: 1px solid #e0e0e0;
    background: #fff;
    flex-shrink: 0;
}

.main-header h3 {
    margin: 0;
    font-size: 1.15rem;
    font-weight: 700;
}

.header-description {
    font-size: 0.85rem;
    color: #777;
    margin-top: 2px;
    display: block;
}

.no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    font-size: 1.1rem;
}

